from dns import answer, encode_response, MessageError, RecordError, ZoneError

def mkquery(name, qtype=1, qclass=1, qid=0x1234, flags=0x0100):
    out = bytearray()
    out += qid.to_bytes(2, "big") + flags.to_bytes(2, "big")
    out += (1).to_bytes(2, "big") + b"\x00" * 6
    for label in name.rstrip(".").split("."):
        out.append(len(label)); out += label.encode()
    out.append(0)
    out += qtype.to_bytes(2, "big") + qclass.to_bytes(2, "big")
    return bytes(out)

def rr(name, rrtype=1, rrclass=1, ttl=300, rdata=b"\x01\x02\x03\x04"):
    return {"name": name, "type": rrtype, "class": rrclass, "ttl": ttl, "rdata": rdata}

def parse(resp):
    flags = int.from_bytes(resp[2:4], "big")
    return {"rcode": flags & 0xF, "an": int.from_bytes(resp[6:8], "big"),
            "ns": int.from_bytes(resp[8:10], "big")}

def read_name(resp, pos):
    labels = []; end = None
    while True:
        b = resp[pos]
        if b == 0: pos += 1; break
        if b & 0xC0 == 0xC0:
            t = ((b & 0x3F) << 8) | resp[pos+1]
            if end is None: end = pos + 2
            pos = t; continue
        labels.append(resp[pos+1:pos+1+b].decode()); pos += 1 + b
    return ".".join(labels) + ".", (end if end is not None else pos)

def an_names(resp):
    n = int.from_bytes(resp[6:8], "big"); pos = 12
    _, pos = read_name(resp, pos); pos += 4
    out = []
    for _ in range(n):
        nm, pos = read_name(resp, pos); out.append(nm)
        pos += 10 + int.from_bytes(resp[pos+8:pos+10], "big")
    return out

